class State(TypedDict):
    messages: Annotated[list, add_messages]
    tokens_used: Annotated[int, operator.add]

def classify(state) -> Command[Literal['sql_node', 'tool_node']]:
    if 'revenue' in state['q']:
        return Command(update={'route': 'sql'}, goto='sql_node')
    return Command(update={'route': 'tool'}, goto='tool_node')
